import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    s = [int(x) for x in data[1:1 + n]]
    m = max(s)
    spf = list(range(m + 1))
    r = int(m ** 0.5) + 1
    small_primes = [p for p in range(2, r + 1) if all(p % d for d in range(2, int(p ** 0.5) + 1))]
    for p in reversed(small_primes):
        if p * p <= m:
            spf[p * p::p] = [p] * len(range(p * p, m + 1, p))
    parent = list(range(m + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    first = [0] * n
    for i in range(n):
        v = s[i]
        if v == 1:
            continue
        p0 = spf[v]
        first[i] = p0
        while v > 1:
            p = spf[v]
            while v % p == 0:
                v //= p
            a, b = find(p0), find(p)
            if a != b:
                parent[b] = a
    cnt = {}
    for i in range(n):
        if first[i]:
            r0 = find(first[i])
            cnt[r0] = cnt.get(r0, 0) + 1
    print(' '.join(str(cnt[find(first[i])] if first[i] else 1) for i in range(n)))

main()

